import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { signOut, useAuth, refreshProfile } from "@/lib/auth";
import { getSupabase } from "@/lib/supabase";
import { DEFAULT_PHOTO } from "@/lib/ciliz-default-photo";
import {
  Heart,
  Plus,
  X,
  LogOut,
  LoaderCircle,
} from "lucide-react";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: "Şüşə Oyunu — Ana Səhifə" },
      {
        name: "description",
        content: "Profilin, oyunçu nömrən və şüşə oyununa giriş.",
      },
      { property: "og:title", content: "Şüşə Oyunu — Ana Səhifə" },
      {
        property: "og:description",
        content: "Şüşə oyununa qoşul, digər oyunçularla oyna.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: Home,
});

function Home() {
  const auth = useAuth();
  const navigate = useNavigate();
  const [uploading, setUploading] = useState(false);
  const [notice, setNotice] = useState("");
  useEffect(() => {
    if (auth.ready && (!auth.session || !auth.profile))
      void navigate({ to: "/auth" });
  }, [auth.ready, auth.session, auth.profile, navigate]);
  const p = auth.profile;
  if (!p)
    return (
      <main className="grid min-h-dvh place-items-center bg-background text-foreground">
        Yüklənir…
      </main>
    );

  const upload = async (file: File) => {
    const sb = getSupabase();
    if (!sb) return;
    setUploading(true);
    setNotice("");
    try {
      if (!file.type.startsWith("image/"))
        throw new Error("Yalnız şəkil faylı seçin.");
      if (file.size > 5 * 1024 * 1024)
        throw new Error("Şəkil 5 MB-dan kiçik olmalıdır.");
      const path = `${p.id}/${Date.now()}.${file.name.split(".").pop() || "jpg"}`;
      const { error } = await sb.storage
        .from("avatars")
        .upload(path, file, { upsert: true, contentType: file.type });
      if (error) throw new Error("Şəkil yüklənmədi.");
      const { data: signed } = await sb.storage
        .from("avatars")
        .createSignedUrl(path, 60 * 60 * 24 * 365);
      if (!signed?.signedUrl) throw new Error("Şəkil yüklənmədi.");
      const { error: saved } = await sb
        .from("profiles")
        .update({ photo_url: signed.signedUrl })
        .eq("id", p.id);
      if (saved) throw new Error("Şəkil yadda saxlanılmadı.");
      await refreshProfile();
    } catch (error) {
      setNotice(
        error instanceof Error ? error.message : "Şəkil yüklənmədi.",
      );
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
      <style>{HOME_STYLES}</style>
      <MobileHomeView
        profile={p}
        defaultPhoto={DEFAULT_PHOTO}
        uploading={uploading}
        notice={notice}
        onPhoto={(file) => void upload(file)}
        onJoin={() => void navigate({ to: "/game" })}
        onSignOut={() => void signOut()}
      />
    </>
  );
}

const BOTTLE_IMAGE =
  "data:image/webp;base64,";
const DEMO_PHOTOS = [
  "data:image/webp;base64,",
  "data:image/webp;base64,",
  "data:image/webp;base64,",
] as const;
const collage = "data:image/webp;base64,";
const bot = "data:image/webp;base64,";
